import {createFloorModel} from './indoor-model.js';
const $=s=>document.querySelector(s), params=new URLSearchParams(location.search), floors=['BF','1F','2F','3F','4F','5F'];
const buildingFloors={B:['1F','2F','3F','4F','5F'],F:floors,G:floors};
const building=Object.hasOwn(buildingFloors,params.get('building'))?params.get('building'):'G',floor=buildingFloors[building].includes(params.get('floor'))?params.get('floor'):'1F';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>s.normalize('NFKC').toUpperCase().replace(/[\s._—–-]/g,'');
let records=[],rooms=[],data,selected=null,origin=null,model,navOpen=false,picking=false,top=false;
const place=r=>/^(AB|BC|EF|FG|GA)-/.test(r.id||'')?`${r.id.split('-')[0]} 连廊 · ${r.floor}（${r.building} 侧图）`:`${r.building} 栋 · ${r.floor}`;
const key=r=>`${r.building}/${r.floor}/${r.id}`;
function goto(b,f,r){if(!buildingFloors[b].includes(f))f='1F';const q=new URLSearchParams({building:b,floor:f});if(r)q.set('room',r);if(origin)q.set('origin',JSON.stringify(origin));location.href='indoor.html?'+q;}
function resultList(){const q=normalize($('#search-input').value),found=rooms.filter(r=>q?(normalize(r.id).includes(q)||normalize(r.label||'').includes(q)):r.building===building&&r.floor===floor);$('#result-count').textContent=`${found.length} 个结果${q?' · B / F / G 全部楼层':' · 本层'}`;$('#search-results').innerHTML=found.length?found.map(r=>`<button class="result ${selected&&key(r)===key(selected)?'current':''}" data-room="${key(r)}"><span class="result-icon">⌖</span><span><strong>${escape(r.id)}</strong><small>${place(r)}${r.label&&r.label!=='用途待确认'?' · '+escape(r.label):''}</small></span><span class="arrow">↗</span></button>`).join(''):'<p class="empty">未找到已录入的编号。<br>请核对原图；未读清的房间没有补造编号。</p>';$('#clear-search').hidden=!$('#search-input').value;}
function openSearch(){resultList();$('#search-panel').hidden=false;$('#search-input').setAttribute('aria-expanded','true')}
function closeSearch(){$('#search-panel').hidden=true;$('#search-input').setAttribute('aria-expanded','false');$('#search-input').blur()}
function render(){const same=origin&&selected&&origin.building===selected.building&&origin.floor===selected.floor;$('#room-name').textContent=selected?.id||'选择教室';$('#room-use').textContent=selected?.label&&selected.label!=='用途待确认'?selected.label:'搜索或点击地图编号';$('#place-location').textContent='目的地 · '+(selected?place(selected):`${building} 栋 ${floor}`);$('#go').disabled=!selected;$('#nav-destination').textContent=selected?.id||'—';model?.setSelected(selected?.id);model?.setMarkers(origin,navOpen||origin?selected:null);$('#show-journey').disabled=!origin||!selected;$('#show-journey').textContent=origin?'查看起终点':'请先选择起点';$('#nav-status').textContent=origin?.id&&selected?.id===origin.id&&origin.floor===selected.floor?'起点与目的地为同一房间（连廊可能出现在两栋图纸中）。':!origin?'选择起终点后，可核对它们的位置。':same?(origin.id&&origin.id===selected?.id?'起点与目的地为同一房间。':'已标记本层起终点。门口与走廊待核验，暂不生成路线。'):`起点在 ${origin.building} 栋 ${origin.floor}；本图显示终点。跨层/跨栋连接待核验。`;}
function selectRoom(k){const r=rooms.find(r=>key(r)===k);if(!r)return;if(r.building!==building||r.floor!==floor){goto(r.building,r.floor,r.id);return;}selected=r;$('#search-input').value=r.id;closeSearch();render();model?.focus(r.id);const url=new URL(location);url.searchParams.set('room',r.id);history.replaceState(null,'',url)}
function navigation(on){navOpen=on;$('#navigation').hidden=!on;$('#destination-card').hidden=on;$('.app').classList.toggle('nav-open',on);render()}
function setPicking(on){picking=on;model?.setPicking(on);$('.app').classList.toggle('picking',on);$('#pick-tip').hidden=!on;$('#navigation').hidden=on||!navOpen;$('#destination-card').hidden=on||navOpen;if(on){closeSearch();model?.fit()}}
function modal(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;$('#info-dialog').showModal()}
function source(){modal(`${building} 栋 ${floor} · 原图`, `<p>图纸照片未经测绘校正；模型高度为示意。放大原始照片核对编号和门口。</p><div class="source-page-list">${data.sourcePages.map(p=>`<a href="${building.toLowerCase()}-assets/source-${String(p).padStart(2,'0')}.jpg" target="_blank" rel="noopener">第 ${p} 页 ↗</a>`).join('')}</div><img class="source-photo" src="${data.image}" alt="${building} 栋 ${floor} 平面展示牌"><h3>本层待复核</h3><ul class="note-list">${data.notes.map(s=>`<li>${escape(s)}</li>`).join('')}</ul>`)}
$('#building-select').value=building;$('#floor-select').innerHTML=buildingFloors[building].map(f=>`<option>${f}</option>`).join('');$('#floor-select').value=floor;$('#building-select').onchange=e=>goto(e.target.value,floor);$('#floor-select').onchange=e=>goto(building,e.target.value);$('#floor-emblem').innerHTML=building+'<span>'+floor+'</span>';$('#map-caption').innerHTML=`${building} 栋 · ${floor}<br><small>拖动旋转 · 双指缩放</small>`;document.title=`寻课 · ${building} 栋 ${floor}`;
$('#search-input').onfocus=openSearch;$('#search-input').oninput=openSearch;$('#search-form').onsubmit=e=>{e.preventDefault();const b=$('#search-results [data-room]');if(b)selectRoom(b.dataset.room)};$('#search-results').onclick=e=>{const b=e.target.closest('[data-room]');if(b)selectRoom(b.dataset.room)};$('#close-search').onclick=closeSearch;$('#clear-search').onclick=()=>{$('#search-input').value='';openSearch();$('#search-input').focus()};
$('#go').onclick=()=>{closeSearch();navigation(true)};$('#close-nav').onclick=()=>{setPicking(false);navigation(false)};$('#change-destination').onclick=()=>{$('#search-input').value='';openSearch();$('#search-input').focus()};$('#origin-select').onchange=e=>{origin=rooms.find(r=>key(r)===e.target.value)||null;render()};$('#pick-position').onclick=()=>setPicking(true);$('#cancel-pick').onclick=()=>setPicking(false);$('#show-journey').onclick=()=>{navigation(false);model?.fit();if(origin&&(origin.building!==building||origin.floor!==floor))modal('跨层起终点',`<p>起点：${escape(origin.id||'手动位置')} · ${origin.building} 栋 ${origin.floor}</p><p>终点：${escape(selected.id)} · ${selected.building} 栋 ${selected.floor}</p><p>楼梯、电梯和连廊的通行关系尚未核验，暂不提供连接路线。</p><button class="dialog-action" id="visit-origin">查看起点楼层 ↗</button>`)};
$('#fit').onclick=()=>{model?.fit();top=false;$('#view-toggle').textContent='2D'};$('#zoom-in').onclick=()=>model?.zoom(.75);$('#zoom-out').onclick=()=>model?.zoom(1.3);$('#view-toggle').onclick=()=>{top=!top;top?model?.setTopView():model?.fit();$('#view-toggle').textContent=top?'3D':'2D';$('#view-toggle').setAttribute('aria-label',top?'切换三维地图':'切换俯视地图')};
$('#source-open').onclick=source;$('#about').onclick=()=>modal('关于这张地图',`<p>B 栋 1–5F，F / G 栋 BF–5F。每层独立建立照片坐标下的空间模型，原图保留在地面用于核对。</p><p>已描摹的房间边界立体显示；其余细节保留在原图中，不能视为已完成独立建模。墙高、墙厚为示意，缺少实测尺寸。</p><p>搜索收录可读编号；虚线标签表示仅定位、尚无独立房间边界。导航现阶段支持起终点预览，不含自动定位、转弯指引或距离估算。</p><ul class="note-list">${(data?.notes||[]).map(s=>`<li>${escape(s)}</li>`).join('')}</ul>`);$('#close-dialog').onclick=()=>$('#info-dialog').close();$('#dialog-body').onclick=e=>{if(e.target.id==='visit-origin')goto(origin.building,origin.floor,origin.id)};
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.search-area'))closeSearch()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeSearch();if(picking)setPicking(false);else if(navOpen)navigation(false)}});
try{
 records=await Promise.all(Object.keys(buildingFloors).flatMap(b=>buildingFloors[b].map(async f=>{const response=await fetch(`indoor/${b.toLowerCase()}-${f}.json`);if(!response.ok)return null;return response.json()})));
 records=records.filter(Boolean).map(d=>{if(d.building==='F'){const indexed=F_DATA.rooms.filter(r=>r.floor===d.floor);const shapes=new Map(d.rooms.map(r=>[r.id,r]));d.rooms=indexed.map(r=>({...r,...shapes.get(r.id),x:r.x,y:r.y}));}return d});
 rooms=records.flatMap(d=>d.rooms.map(r=>({...r,building:d.building,floor:d.floor})));data=records.find(d=>d.building===building&&d.floor===floor);if(!data)throw Error('本层数据未加载');
 selected=rooms.find(r=>r.building===building&&r.floor===floor&&r.id===params.get('room'))||rooms.find(r=>r.building===building&&r.floor===floor&&r.id===({B:'B-1019',F:'F-1021',G:'G-1006'}[building]))||null;
 try{const raw=JSON.parse(params.get('origin'));if(raw&&Object.hasOwn(buildingFloors,raw.building)&&buildingFloors[raw.building].includes(raw.floor)&&Number.isFinite(raw.x)&&Number.isFinite(raw.y))origin=raw;}catch{}
 $('#origin-select').innerHTML+='<option value="manual" disabled>地图上的手动位置</option>'+records.map(d=>`<optgroup label="${d.building} 栋 ${d.floor}">${d.rooms.map(r=>`<option value="${d.building}/${d.floor}/${escape(r.id)}">${escape(r.id)}</option>`).join('')}</optgroup>`).join('');if(origin)$('#origin-select').value=origin.id?key(origin):'manual';
 $('#map-fallback img').src=data.image;
 model=await createFloorModel($('#model-host'),data,{select:id=>selectRoom(`${building}/${floor}/${id}`),position:p=>{origin={building,floor,...p};$('#origin-select').value='manual';setPicking(false);render()}});
 $('#loading').hidden=true;model.setActive(true);render();if(selected&&params.get('room'))model.focus(selected.id);if(params.get('q')){$('#search-input').value=params.get('q');openSearch()}
}catch(error){console.error(error);$('#loading').hidden=true;$('#map-fallback').hidden=false;$('#model-host').hidden=true;$('#pick-position').disabled=true;$('#nav-status').textContent='地图加载失败，请刷新或核对原图。'}
